INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES
(41671,0,0,'I can\'t wait to get home to my family. Thank you, stranger.',12,0,100,0,0,0,0,0,'Trapped Miner - rescued'),
(41671,0,1,'I thought I would die down here.',12,0,100,0,0,0,0,0,'Trapped Miner - rescued'),
(41671,0,2,'I thought they were going to tear me apart!',12,0,100,0,0,0,0,0,'Trapped Miner - rescued'),
(41671,0,3,'Light bless you, stranger. You\'ve saved me!',12,0,100,0,0,0,0,0,'Trapped Miner - rescued'),
(41671,0,4,'Thank you!',12,0,100,0,0,0,0,0,'Trapped Miner - rescued'),
(41671,0,5,'You\'re the best thing I\'ve seen since the troggs showed up!',12,0,100,0,0,0,0,0,'Trapped Miner - rescued'),
(45966,0,0,'We have to break through those mindless leper gnomes if we want to get out of here alive!',12,0,100,25,0,0,46382,0,'Nevin Twistwrench'),
(46025,0,0,'This path only leads deeper into the city. Keep going south toward the Loading Room.',12,0,100,5,0,0,47191,0,'S.A.F.E. Officer'),
(46230,0,0,'Ugh! Not this again! I\'m asking for a new station next expedition...',12,0,100,1,0,0,46342,0,'S.A.F.E. Technician'),
(46230,1,0,'No, not the Sanitron... it was my pride and joy!',12,0,100,6,0,0,46341,0,'S.A.F.E. Technician'),
(46268,0,0,'Please help me!',12,0,100,20,0,0,46385,0,'Survivor'),
(46268,0,1,'I don\'t want to die down here!',12,0,100,18,0,0,46386,0,'Survivor'),
(46268,0,2,'Don\'t let them eat me!',12,0,100,20,0,0,46387,0,'Survivor'),
(46268,0,3,'Some help! Anyone!',12,0,100,18,0,0,46388,0,'Survivor'),
(46268,0,4,'I\'m too young to die!',12,0,100,18,0,0,46389,0,'Survivor'),
(46268,0,5,'I\'m really going to die down here, aren\'t I?',12,0,100,18,0,0,46390,0,'Survivor'),
(46268,0,6,'Help! I\'m too weak to make it on my own.',12,0,100,20,0,0,46391,0,'Survivor'),
(46449,0,0,'Stay with me. You\'re going to make it out of here.',12,0,100,0,0,0,46501,0,'S.A.F.E. Operative'),
(46449,1,0,'We\'re going to get you some help.',12,0,100,0,0,0,46502,0,'S.A.F.E. Operative');
